/*
 * One script from the fork: core, emitter, the 37 grammars, and the entry.
 *
 *   node third_party/highlight.js/build.mjs   →  build/highlight.lamassu.js
 *
 * No bundler. lamassu has no module system and rejects `var`, and esbuild's
 * module wrappers are made of `var` — so each file is wrapped in a function
 * of its own here, in the order the scopes need: the grammars are CommonJS
 * and get a `module` to export through, the core leaves an instance behind,
 * the emitter sees it as `HighlightJs`, and the entry sees both. The result
 * is plain script, the same under node and under lamassu, which is what
 * lets check.mjs run it in both and say which side a difference is on.
 */
import { mkdirSync, readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const pkg = join(here, '..', '..');

export function bundle() {
  const read = (name) => readFileSync(join(here, name), 'utf8');
  const versions = read('VERSION').trim().replace(/\n/g, ', ');

  const grammars = readdirSync(join(here, 'languages'))
    .filter((f) => f.endsWith('.js'))
    .sort()
    .map((f) => {
      const name = f.slice(0, -3);
      const source = readFileSync(join(here, 'languages', f), 'utf8');
      return `  ${JSON.stringify(name)}: (function () {\n` +
        `    const module = { exports: null };\n` +
        `${source}\n` +
        `    return module.exports;\n` +
        `  })(),`;
    });

  return [
    `/* GENERATED by third_party/highlight.js/build.mjs — do not edit.`,
    ` * highlight.js in lamassu's subset: ${versions}, ${grammars.length} grammars. */`,
    ``,
    `const __hljs = (function () {`,
    `  const ALIASES = ${read('aliases.json').trim()};`,
    `  const KEYWORD_SCOPES = ${read('keyword-scopes.json').trim()};`,
    read('core.js'),
    `  return highlight;`,
    `})();`,
    ``,
    `const __lowlight = (function () {`,
    `  const HighlightJs = __hljs;`,
    read('lowlight.js'),
    `  return createLowlight;`,
    `})();`,
    ``,
    `const __grammars = {`,
    ...grammars,
    `};`,
    ``,
    read('entry.js'),
    ``,
  ].join('\n');
}

/** The bundle as an ES module: what the engine loads as "mdy-docs/highlight". */
export function moduleSource() {
  return bundle() + '\nexport { highlightCode, highlightRegistered };\n';
}

/**
 * The module source as a C string constant, for src/engine.c to embed.
 * Octal escapes for everything outside printable ASCII — a hex escape is
 * greedy and would eat a hex digit that follows — and `?` escaped so no
 * trigraph can form; one literal per line, which the compiler concatenates.
 */
export function cHeader() {
  const bytes = Buffer.from(moduleSource(), 'utf8');
  const lines = [];
  let line = '';
  for (const b of bytes) {
    let piece;
    if (b === 0x22) piece = '\\"';
    else if (b === 0x5c) piece = '\\\\';
    else if (b === 0x3f) piece = '\\?';
    else if (b === 0x0a) piece = '\\n';
    else if (b === 0x09) piece = '\\t';
    else if (b >= 0x20 && b < 0x7f) piece = String.fromCharCode(b);
    else piece = '\\' + b.toString(8).padStart(3, '0');
    line += piece;
    if (b === 0x0a || line.length >= 100) { lines.push(`"${line}"`); line = ''; }
  }
  if (line) lines.push(`"${line}"`);
  return [
    `/* GENERATED by third_party/highlight.js/build.mjs — do not edit. */`,
    `#ifndef MDY_HIGHLIGHT_BUNDLE_H`,
    `#define MDY_HIGHLIGHT_BUNDLE_H`,
    `/* highlight.js in lamassu's subset, as an ES module; see third_party/highlight.js. */`,
    `static const char MDY_HIGHLIGHT_MODULE[] =`,
    ...lines,
    `;`,
    `#endif`,
    ``,
  ].join('\n');
}

export const OUTPUT = join(pkg, 'build', 'highlight.lamassu.js');

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const at = process.argv.indexOf('--c-header');
  if (at !== -1) {
    const out = process.argv[at + 1];
    mkdirSync(dirname(out), { recursive: true });
    const header = cHeader();
    writeFileSync(out, header);
    console.log(`${out}: ${(header.length / 1024).toFixed(0)} KB`);
  } else {
    const source = bundle();
    mkdirSync(dirname(OUTPUT), { recursive: true });
    writeFileSync(OUTPUT, source);
    console.log(`${OUTPUT}: ${(source.length / 1024).toFixed(0)} KB`);
  }
}
